CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, default_locale varchar(10) NOT NULL DEFAULT 'en', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), subject text NOT NULL, display_name text NOT NULL, preferred_locale varchar(10) NOT NULL DEFAULT 'en', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS engagements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, locale varchar(10) NOT NULL DEFAULT 'en', status varchar(32) NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), engagement_id uuid NOT NULL REFERENCES engagements(id), translation_group_id uuid, language varchar(2) NOT NULL, locale varchar(10) NOT NULL, status varchar(40) NOT NULL DEFAULT 'draft', version text NOT NULL DEFAULT '1', content_ref text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), type text NOT NULL, actor_type varchar(32) NOT NULL, actor_id uuid, correlation_id text NOT NULL, payload text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
